#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Ns/m²".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::NewtonSecondPerMeterSquared)
    );
    assert_eq!(
        format!("2.5 {}", "Ns/m²").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(
            2.5,
            DynamicViscosityUnit::NewtonSecondPerMeterSquared
        ))
    );
    assert_eq!(
        "Pa·s".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::PascalSecond)
    );
    assert_eq!(
        format!("2.5 {}", "Pa·s").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(
            2.5,
            DynamicViscosityUnit::PascalSecond
        ))
    );
    assert_eq!(
        "PaS".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::PascalSecond)
    );
    assert_eq!(
        format!("2.5 {}", "PaS").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(
            2.5,
            DynamicViscosityUnit::PascalSecond
        ))
    );
    assert_eq!(
        "mPa·s".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::MillipascalSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mPa·s").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(
            2.5,
            DynamicViscosityUnit::MillipascalSecond
        ))
    );
    assert_eq!(
        "µPa·s".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::MicropascalSecond)
    );
    assert_eq!(
        format!("2.5 {}", "µPa·s").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(
            2.5,
            DynamicViscosityUnit::MicropascalSecond
        ))
    );
    assert_eq!(
        "P".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::Poise)
    );
    assert_eq!(
        format!("2.5 {}", "P").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(2.5, DynamicViscosityUnit::Poise))
    );
    assert_eq!(
        "cP".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::Centipoise)
    );
    assert_eq!(
        format!("2.5 {}", "cP").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(2.5, DynamicViscosityUnit::Centipoise))
    );
    assert_eq!(
        "reyn".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::Reyn)
    );
    assert_eq!(
        format!("2.5 {}", "reyn").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(2.5, DynamicViscosityUnit::Reyn))
    );
    assert_eq!(
        "lbf·s/in²".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::PoundForceSecondPerSquareInch)
    );
    assert_eq!(
        format!("2.5 {}", "lbf·s/in²").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(
            2.5,
            DynamicViscosityUnit::PoundForceSecondPerSquareInch
        ))
    );
    assert_eq!(
        "lbf·s/ft²".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::PoundForceSecondPerSquareFoot)
    );
    assert_eq!(
        format!("2.5 {}", "lbf·s/ft²").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(
            2.5,
            DynamicViscosityUnit::PoundForceSecondPerSquareFoot
        ))
    );
    assert_eq!(
        "lb/(ft·s)".parse::<DynamicViscosityUnit>(),
        Ok(DynamicViscosityUnit::PoundPerFootSecond)
    );
    assert_eq!(
        format!("2.5 {}", "lb/(ft·s)").parse::<DynamicViscosity>(),
        Ok(DynamicViscosity::new(
            2.5,
            DynamicViscosityUnit::PoundPerFootSecond
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<DynamicViscosity>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = DynamicViscosity::from_base(6.0);
    let b = DynamicViscosity::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = DynamicViscosity::<i64>::from_base(7);
    let b = DynamicViscosity::<i64>::from_base(2);
    assert_eq!(a + b, DynamicViscosity::from_base(9));
    assert_eq!(a % b, DynamicViscosity::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<DynamicViscosity<i64>>(),
        DynamicViscosity::from_base(9)
    );
}
